function parseCsvLine(line) {
  const fields = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"';
        i += 1;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === ',' && !inQuotes) {
      fields.push(current.trim());
      current = '';
    } else {
      current += ch;
    }
  }
  fields.push(current.trim());
  return fields;
}

function getUnuploadedCampuses() {
  return RAW_UNUPLOADED_CSV.trim()
    .split(/\r?\n/)
    .map((line) => {
      const f = parseCsvLine(line);
      return {
        serial_no: Number(f[0]) || 0,
        institution_name: (f[1] || '').trim(),
        place: (f[2] || '').trim(),
        district: (f[3] || '').trim(),
        state: (f[4] || 'Kerala').trim(),
        supervisor_name: (f[5] || '').trim(),
        supervisor_phone: (f[6] || '').trim(),
        supervisor_email: (f[7] || '').trim(),
        enrolled_students: Number(f[8]) || 0,
        winners_declared: Number(f[9]) || 0,
        submission_status: (f[10] || 'No Enrolled Students').trim(),
      };
    });
}

module.exports = { getUnuploadedCampuses };
